BEGIN;
INSERT INTO public.tac_academy_courses (slug,title,lessons,questions,answer_key) VALUES ('financial-planning-cfp-prep','Comprehensive Financial Planning · CFP® Prep','[{"id":"start","title":"Start here and choose a pace","html":"<h3>Start here and choose a pace</h3><p>This independent Valtoris training course is for advisors learning comprehensive financial planning and candidates supplementing their CFP® education. Official coursework and capstone credit come through a CFP Board Registered Program. Certification also requires the degree, examination, experience and ethics requirements.</p><p>Use the lesson menu to open the pathway, the six coursework areas, practice cases and the capstone. Read a topic, solve its check closed-book, and show your reasoning. Mark completed work to resume later.</p><h4>Suggested pace</h4><ol><li>24 weeks alongside work: give each of the first six courses three weeks. Use weeks 19–21 for the capstone and weeks 22–24 for review and timed practice.</li><li>36 weeks for learners new to financial planning: give each of the first six courses five weeks. Use weeks 31–34 for the capstone and weeks 35–36 to review.</li><li>Weekly rhythm: read, work the exercise without notes, discuss a case, and revisit an earlier weak topic.</li></ol><h4>Credential checklist</h4><ol><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/certification-process/education-requirement/certification-coursework-requirement/what-youll-learn\">CFP Board coursework and domains</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/certification-process/education-requirement/bachelors-degree-requirement\">Degree requirement</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/certification-process/experience-requirement\">Experience pathways</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/certification-process/exam-requirement\">Exam and handbook</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/certification-process/ethics-requirement\">Ethics requirement</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/about-cfp-board/competency-standards\">Phased updates to competency standards</a></li></ol>"},{"id":"map","title":"Program comparison, exam map and sources","html":"<h3>Program comparison, exam map and sources</h3><table><thead><tr><th>Program</th><th>Public design</th><th>What this course takes from it</th></tr></thead><tbody><tr><td>Kaplan / College for Financial Planning</td><td>Seven courses, unit and case checks, finals, written and presented plan</td><td>Seven-course sequence and applied assessments</td></tr><tr><td>Boston University</td><td>Sequential online certificate with integrated capstone</td><td>Sequencing and cumulative review</td></tr><tr><td>UT Austin</td><td>Seven instructor-led courses with plan development</td><td>Discussion, coached feedback and presentation rubric</td></tr><tr><td>Dalton Education</td><td>Capstone and a separate exam review offering</td><td>Finish applied plan work before an independent timed review</td></tr></tbody></table><h4>Official exam emphasis</h4><ol><li>Conduct and regulation · 8%</li><li>Planning principles · 15%</li><li>Risk and insurance · 11%</li><li>Investments · 17%</li><li>Tax · 14%</li><li>Retirement · 18%</li><li>Estate · 10%</li><li>Client psychology · 7%</li></ol><p>Use the candidate handbook and the current exam-window tax tables. The official examination has 170 questions across two three-hour sessions. The Academy review checks recall across 70 topics.</p><ol><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/certification-process/education-requirement/certification-coursework-requirement/what-youll-learn\">CFP Board Principal Knowledge Topics</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.kaplanfinancial.com/cfp/education-program\">Kaplan education program</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://cpe.bu.edu/financial-planning/\">Boston University curriculum</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://professionaled.utexas.edu/s/program/a1Wcs00000075Xn/financial-planning-certificate-program\">UT Austin financial planning certificate</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://dalton-education.com/cfp-capstone\">Dalton capstone</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.irs.gov/forms-instructions\">IRS publications and year-specific instructions</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.ssa.gov/retirement\">Social Security planning</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.medicare.gov/\">Medicare enrollment and coverage</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.investor.gov/\">SEC investor education</a></li></ol>"},{"id":"video","title":"Watch and discuss","html":"<h3>Watch and discuss</h3><ol><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2021/01/case-study--financial-advice-that-requires-financial-planning\">CFP Board ethics case video: When financial advice requires financial planning</a> · Identify the advice, the affected areas and why the scope matters.</li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/-/media/files/cfp-board/standards-and-ethics/compliance-resources/guide-to-financial-planning-process.pdf\">CFP Board guide to the planning process</a> · Compare the example with your own case memo.</li></ol>"},{"id":"course-1","title":"Course 1 · Planning foundations, ethics and client psychology","html":"<h3>Course 1 · Planning foundations, ethics and client psychology</h3><p>Complete the 22 topics below, then solve the applied case in the lesson menu. Explain the decision, assumptions and what would change your recommendation.</p><ol><li>Topic 1 · Ethical duties</li><li>Topic 2 · Discipline and procedure</li><li>Topic 3 · Financial institutions</li><li>Topic 4 · Regulatory roles and registration</li><li>Topic 5 · Consumer protection</li><li>Topic 6 · Fiduciary judgment</li><li>Topic 7 · Planning process</li><li>Topic 8 · Statements and ratios</li><li>Topic 9 · Managing cash flow</li><li>Topic 10 · Debt and financing</li><li>Topic 11 · Economic conditions</li><li>Topic 12 · Time value of money</li><li>Topic 13 · Education needs analysis</li><li>Topic 14 · Education savings vehicles</li><li>Topic 15 · Education funding</li><li>Topic 16 · Education gifts and tax coordination</li><li>Topic 65 · Client and advisor values</li><li>Topic 66 · Behavioral finance</li><li>Topic 67 · Sources of money conflict</li><li>Topic 68 · Counseling skills</li><li>Topic 69 · Communication and comprehension</li><li>Topic 70 · Crisis response</li></ol>"},{"id":"topic-1","title":"Topic 1 · Ethical duties","html":"<h3>Topic 1 · Ethical duties</h3><p>Identify whether the activity is financial advice and document conflicts, compensation, privacy and the scope of work. Apply the duties of loyalty, care and following lawful client instructions. A referral payment creates a conflict even when the referred product fits.</p><h4>Knowledge check</h4><p>An advisor gets a higher commission on two otherwise similar products. What must happen before recommending the higher-paying one?</p><details><summary>Reveal answer</summary><p>Assess alternatives, disclose material conflict, obtain informed consent and manage the conflict. Recommend based on client interests.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-2","title":"Topic 2 · Discipline and procedure","html":"<h3>Topic 2 · Discipline and procedure</h3><p>Distinguish standards of conduct from the process used to investigate and resolve alleged violations. Track reportable events, preserve records and read the response and appeal dates on the relevant notice. CFP Board discipline and regulatory proceedings can run separately.</p><h4>Knowledge check</h4><p>An advisor receives a CFP Board notice about a regulator’s findings. Does the regulator’s closure automatically close the Board matter?</p><details><summary>Reveal answer</summary><p>No. Review the notice and follow the Board’s separate procedures.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-3","title":"Topic 3 · Financial institutions","html":"<h3>Topic 3 · Financial institutions</h3><p>A bank holds deposits, a broker executes securities transactions, an adviser provides advice, a custodian holds assets and an insurer assumes specified risks. FDIC protection concerns eligible bank deposits and SIPC addresses qualifying missing assets at failed member brokerages, subject to limits.</p><h4>Knowledge check</h4><p>A stock falls 30% at a solvent broker. Which protection reimburses the loss?</p><details><summary>Reveal answer</summary><p>Neither FDIC nor SIPC covers the market decline.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-4","title":"Topic 4 · Regulatory roles and registration","html":"<h3>Topic 4 · Regulatory roles and registration</h3><p>Determine the activity first. Federal or state advisers, broker-dealers and insurance producers have different registration and conduct rules. Review Form ADV and Form CRS where applicable. A planning credential does not grant permission to sell a regulated product.</p><h4>Knowledge check</h4><p>A planner with only a planning designation wants to sell an insurance policy. What comes first?</p><details><summary>Reveal answer</summary><p>Verify the relevant producer license and authority.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-5","title":"Topic 5 · Consumer protection","html":"<h3>Topic 5 · Consumer protection</h3><p>Check permitted uses and safeguards for client data, credit disclosures and fair-lending obligations. GLBA concerns financial privacy, FCRA concerns consumer reports and ECOA addresses credit discrimination. Limit access to what the task requires.</p><h4>Knowledge check</h4><p>An application is denied based partly on a credit report. Which law principally governs notice concerning the report?</p><details><summary>Reveal answer</summary><p>FCRA</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-6","title":"Topic 6 · Fiduciary judgment","html":"<h3>Topic 6 · Fiduciary judgment</h3><p>A recommendation should tie the client’s needs, risk capacity and alternatives to the proposed action. Compare cost, liquidity, tax, guarantees and surrender terms. Document why the recommendation works and which conflicts were handled.</p><h4>Knowledge check</h4><p>A retiree needs $40,000 within one year. Two products have similar benefits, but one locks the funds for seven years. What factor can determine the recommendation?</p><details><summary>Reveal answer</summary><p>Liquidity relative to the client’s actual spending need.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-7","title":"Topic 7 · Planning process","html":"<h3>Topic 7 · Planning process</h3><p>Understand circumstances, select goals, analyze the current course and alternatives, develop and present recommendations, implement assigned actions, and monitor and update as agreed. If data is missing, obtain it or narrow the engagement appropriately.</p><h4>Knowledge check</h4><p>A client requests a rollover recommendation but cannot supply the plan’s fee and distribution terms. What is the next step?</p><details><summary>Reveal answer</summary><p>Gather those facts before finalizing the comparison.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-8","title":"Topic 8 · Statements and ratios","html":"<h3>Topic 8 · Statements and ratios</h3><p>A balance sheet measures assets minus liabilities on a date. A cash-flow statement records inflows less outflows over a period. Track liquidity, debt payments and savings against a consistently defined income base.</p><h4>Knowledge check</h4><p>Assets are $420,000 and liabilities $265,000. What is net worth?</p><details><summary>Reveal answer</summary><p>$155,000</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-9","title":"Topic 9 · Managing cash flow","html":"<h3>Topic 9 · Managing cash flow</h3><p>Separate fixed, variable and irregular expenses. Use monthly equivalents for annual bills and test reserve targets against essential expenses and income volatility. Treat transfers to savings consistently so they are not double counted.</p><h4>Knowledge check</h4><p>A self-employed family’s essentials are $5,200 monthly. Its six-month reserve target is?</p><details><summary>Reveal answer</summary><p>$31,200</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-10","title":"Topic 10 · Debt and financing","html":"<h3>Topic 10 · Debt and financing</h3><p>Compare APR, fees, collateral, term and cash-flow flexibility. A lower monthly payment from a longer term can increase total cost. The avalanche method prioritizes the highest effective interest rate, while the snowball prioritizes the smallest balance.</p><h4>Knowledge check</h4><p>Holding payments and all other terms constant, which approach generally minimizes interest?</p><details><summary>Reveal answer</summary><p>Highest effective rate first</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-11","title":"Topic 11 · Economic conditions","html":"<h3>Topic 11 · Economic conditions</h3><p>Distinguish real and nominal values, monetary and fiscal policy, and unemployment and inflation. Unexpected inflation can hurt purchasing power and increase pressure on interest-rate-sensitive assets.</p><h4>Knowledge check</h4><p>Nominal return is 6% and inflation 3%. What is the approximate exact real return?</p><details><summary>Reveal answer</summary><p>2.91%, using 1.06 ÷ 1.03 − 1</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-12","title":"Topic 12 · Time value of money","html":"<h3>Topic 12 · Time value of money</h3><p>Enter N, I/Y, PV, PMT and FV with a consistent period and opposite signs for inflows and outflows. Set END for ordinary annuities and BGN for annuities due. Clear calculator registers. For a lump sum, FV = PV × (1+r)^n.</p><h4>Knowledge check</h4><p>What is $10,000 in three years at 5% annual compounding?</p><details><summary>Reveal answer</summary><p>$11,576.25</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-13","title":"Topic 13 · Education needs analysis","html":"<h3>Topic 13 · Education needs analysis</h3><p>Estimate years until enrollment, school costs, tuition inflation, existing savings and scholarships separately. Inflate today’s cost first and then discount or solve for contributions. Test a lower-return scenario.</p><h4>Knowledge check</h4><p>Tuition is $20,000 today and rises 4% annually for 10 years. What is the first-year projected cost?</p><details><summary>Reveal answer</summary><p>About $29,605</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-14","title":"Topic 14 · Education savings vehicles","html":"<h3>Topic 14 · Education savings vehicles</h3><p>Compare 529 plans, Coverdell accounts, custodial accounts and taxable savings by ownership, control, flexibility and tax treatment. A 529 generally allows qualified education withdrawals with federal tax advantages. Custodial assets become the beneficiary’s at the applicable age.</p><h4>Knowledge check</h4><p>Which vehicle can typically keep the parent as account owner while designating a student beneficiary?</p><details><summary>Reveal answer</summary><p>529 savings plan</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-15","title":"Topic 15 · Education funding","html":"<h3>Topic 15 · Education funding</h3><p>Build a funding ladder using cash flow, savings, grants, scholarships, work and borrowing. Compare federal protections and private-loan underwriting before taking on debt or refinancing. Read each award’s actual terms.</p><h4>Knowledge check</h4><p>Two aid offers differ in grants and unsubsidized loans. Which reduces the student’s cost without creating debt when conditions are met?</p><details><summary>Reveal answer</summary><p>Grant</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-16","title":"Topic 16 · Education gifts and tax coordination","html":"<h3>Topic 16 · Education gifts and tax coordination</h3><p>Coordinate qualified 529 expenses with credits and scholarships so the same expense is not used twice. Distinguish the 529 five-year gift election from the exclusion for qualifying tuition paid directly to an institution. Verify filings and eligibility with the year’s instructions.</p><h4>Knowledge check</h4><p>Which payment can qualify for the direct tuition exclusion when all conditions are met?</p><details><summary>Reveal answer</summary><p>Tuition paid directly to the school</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-65","title":"Topic 65 · Client and advisor values","html":"<h3>Topic 65 · Client and advisor values</h3><p>Ask what the client values before translating goals into numbers. Identify your own product bias and distinguish capacity to absorb losses from willingness to take them.</p><h4>Knowledge check</h4><p>A client can afford risk but panics at drawdowns. What should the planner assess?</p><details><summary>Reveal answer</summary><p>Both financial risk capacity and emotional risk tolerance.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-66","title":"Topic 66 · Behavioral finance","html":"<h3>Topic 66 · Behavioral finance</h3><p>Loss aversion gives losses greater psychological weight. Anchoring fixates on an initial number. Recency extrapolates recent events. Mental accounting treats fungible funds differently. Coach with scenarios and agreed rules.</p><h4>Knowledge check</h4><p>A client refuses to sell solely because the stock is below its original purchase price. Which bias fits?</p><details><summary>Reveal answer</summary><p>Anchoring</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-67","title":"Topic 67 · Sources of money conflict","html":"<h3>Topic 67 · Sources of money conflict</h3><p>Use neutral language and identify whether a dispute concerns priorities, control, financial secrecy or past experiences. Give both spouses space to describe interests and agree on a shared decision rule.</p><h4>Knowledge check</h4><p>Partners disagree about emergency savings versus investing. Which opening is best?</p><details><summary>Reveal answer</summary><p>Ask each partner what concern the money is intended to address.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-68","title":"Topic 68 · Counseling skills","html":"<h3>Topic 68 · Counseling skills</h3><p>Use open questions, reflective listening and a manageable next step. Stay within competence and refer when the client needs mental health, legal or other specialized support.</p><h4>Knowledge check</h4><p>A client overwhelmed by debt misses appointments. What is a useful first step?</p><details><summary>Reveal answer</summary><p>Agree on one doable action and when to check in.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-69","title":"Topic 69 · Communication and comprehension","html":"<h3>Topic 69 · Communication and comprehension</h3><p>Use a one-page explanation with relevant assumptions and invite the client to teach back the trade-off. Record decisions, responsibilities and changes in scope in plain language.</p><h4>Knowledge check</h4><p>How can the planner check whether a client understands a surrender charge?</p><details><summary>Reveal answer</summary><p>Ask the client to explain in their own words what happens if they exit early.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-70","title":"Topic 70 · Crisis response","html":"<h3>Topic 70 · Crisis response</h3><p>After bereavement, job loss or serious illness, triage safety, cash, deadlines and authority first. Defer reversible long-term commitments where feasible. Identify privacy, trusted contacts and possible exploitation.</p><h4>Knowledge check</h4><p>A recent widow requests a large irreversible transfer while confused. What should be prioritized?</p><details><summary>Reveal answer</summary><p>Clarify authority, immediate needs and risks before acting.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"case-1","title":"Applied case 1 · Planning and conduct","html":"<h3>Applied case 1 · Planning and conduct</h3><p>Maya and Jordan earn $150,000 gross and take home $9,400 monthly. Essentials are $5,400, other spending $1,550 and debt minimums $650. Reserves are $13,000. A card charges 21%. Maya’s advisor earns a commission on a product she is considering.</p><h4>Your assignment</h4><p>Calculate surplus and the six-month reserve gap. Compare a reserve-first plan and a split debt/reserve plan. Draft the scope, conflict disclosure and an implementation date.</p><details><summary>Reveal worked solution</summary><p>Monthly surplus is $1,800. Six months of essentials is $32,400, leaving $19,400 before any reclassification of minimum debt payments. Hold enough cash to avoid new high-cost debt, then compare how much interest each plan saves. Disclose and manage the conflict and show a lower-cost alternative.</p></details>"},{"id":"course-2","title":"Course 2 · Insurance, risk and employee benefits","html":"<h3>Course 2 · Insurance, risk and employee benefits</h3><p>Complete the 10 topics below, then solve the applied case in the lesson menu. Explain the decision, assumptions and what would change your recommendation.</p><ol><li>Topic 17 · Risk and insurance mechanisms</li><li>Topic 18 · Exposure inventory</li><li>Topic 19 · Health and group benefits</li><li>Topic 20 · Disability income</li><li>Topic 21 · Long-term care planning</li><li>Topic 22 · Annuity analysis</li><li>Topic 23 · Life insurance comparison</li><li>Topic 24 · Business coverage</li><li>Topic 25 · Quantifying insurance needs</li><li>Topic 26 · Carrier and contract selection</li></ol>"},{"id":"topic-17","title":"Topic 17 · Risk and insurance mechanisms","html":"<h3>Topic 17 · Risk and insurance mechanisms</h3><p>Pure risk has loss or no loss. Frequency and severity guide whether to avoid, reduce, retain or transfer exposure. A deductible retains small losses while coverage can transfer larger losses.</p><h4>Knowledge check</h4><p>Which strategy best describes installing a sprinkler system?</p><details><summary>Reveal answer</summary><p>Risk reduction</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-18","title":"Topic 18 · Exposure inventory","html":"<h3>Topic 18 · Exposure inventory</h3><p>List personal, property, liability and business risks, existing limits and exclusions. Rank by probability and impact. Review annual changes and assume overlapping policies can have different definitions.</p><h4>Knowledge check</h4><p>Which gap should typically be addressed before paying to insure small replaceable items?</p><details><summary>Reveal answer</summary><p>A financially catastrophic exposure the client cannot absorb.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-19","title":"Topic 19 · Health and group benefits","html":"<h3>Topic 19 · Health and group benefits</h3><p>Compare premium, network, deductible, coinsurance and out-of-pocket limit. Distinguish HMO/PPO, COBRA continuation, HSA eligibility and FSA/HRA funding. An HSA is portable and qualified withdrawals can be tax-free.</p><h4>Knowledge check</h4><p>After a $500 remaining deductible on a $2,500 allowed bill, what does the member pay at 20% coinsurance before the cap?</p><details><summary>Reveal answer</summary><p>$900</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-20","title":"Topic 20 · Disability income","html":"<h3>Topic 20 · Disability income</h3><p>Calculate the income gap, then compare own- versus any-occupation definitions, elimination and benefit periods, residual coverage, exclusions and tax treatment. Employer-paid or pretax premiums generally make the related benefits taxable.</p><h4>Knowledge check</h4><p>A policy pays once a 90-day disability waiting period passes. What is that interval called?</p><details><summary>Reveal answer</summary><p>Elimination period</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-21","title":"Topic 21 · Long-term care planning","html":"<h3>Topic 21 · Long-term care planning</h3><p>Compare self-funding, traditional and hybrid coverage. Assess benefit triggers, activities of daily living, cognitive impairment, elimination days, inflation options and caregiving burden. Match policy benefits to the care setting and local costs.</p><h4>Knowledge check</h4><p>Which feature directly addresses rising care costs over time?</p><details><summary>Reveal answer</summary><p>Inflation protection</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-22","title":"Topic 22 · Annuity analysis","html":"<h3>Topic 22 · Annuity analysis</h3><p>Compare fixed, indexed and variable structures, insurer strength, contract expenses and surrender effects. Qualified annuities sit in a tax-qualified arrangement. Nonqualified annuities ordinarily use after-tax dollars and have different withdrawal and annuitization rules. Compare the annuity with the account it will occupy.</p><h4>Knowledge check</h4><p>Why might tax deferral alone be insufficient to justify an annuity inside an IRA?</p><details><summary>Reveal answer</summary><p>The IRA already provides tax deferral.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-23","title":"Topic 23 · Life insurance comparison","html":"<h3>Topic 23 · Life insurance comparison</h3><p>Match duration and premium budget with term or permanent coverage. Model both guaranteed and illustrated values for permanent contracts. Review policy ownership, beneficiary designation, conversion and loans. Group coverage can change when employment ends.</p><h4>Knowledge check</h4><p>A 20-year mortgage is the only coverage need. Which design most directly matches the stated duration?</p><details><summary>Reveal answer</summary><p>Twenty-year term</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-24","title":"Topic 24 · Business coverage","html":"<h3>Topic 24 · Business coverage</h3><p>Analyze liability, property, overhead, key person and buy-sell exposures. Identify who owns the policy, pays and receives proceeds. Coordinate the contract and funded arrangement with legal and tax advisors.</p><h4>Knowledge check</h4><p>A firm wants funds to buy a deceased partner’s interest. What must the insurance align with?</p><details><summary>Reveal answer</summary><p>The buy-sell agreement.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-25","title":"Topic 25 · Quantifying insurance needs","html":"<h3>Topic 25 · Quantifying insurance needs</h3><p>Use a needs approach by adding urgent obligations, income replacement and special goals, then subtracting available assets and existing coverage. Apply present value consistently and discuss liquidity or income assumptions.</p><h4>Knowledge check</h4><p>If stated needs total $900,000 and available assets and existing coverage are $300,000, what is the starting gap?</p><details><summary>Reveal answer</summary><p>$600,000</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-26","title":"Topic 26 · Carrier and contract selection","html":"<h3>Topic 26 · Carrier and contract selection</h3><p>Check financial strength, underwriting, guarantees, exclusions, renewability, fees, product suitability and agent conflicts. Compare in-force evidence before recommending replacement. Anticipate another contestability period or surrender charge where applicable.</p><h4>Knowledge check</h4><p>A new policy has a lower premium. What should be checked before surrendering the existing one?</p><details><summary>Reveal answer</summary><p>Replacement effects and the new policy’s issued terms.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"case-2","title":"Applied case 2 · Risk and employee benefits","html":"<h3>Applied case 2 · Risk and employee benefits</h3><p>A family needs $650,000 for survivor income and $210,000 for debt and one-time costs. It has $100,000 group life and $40,000 earmarked assets. The replacement health plan has a $1,000 deductible, 20% coinsurance and a $5,000 in-network maximum.</p><h4>Your assignment</h4><p>Compute life gap and member cost on the first $8,000 eligible in-network allowed expense. Compare reliance on employer coverage with portable individual coverage.</p><details><summary>Reveal worked solution</summary><p>Initial life need is $720,000. Medical cost is $1,000 plus 20% of $7,000, or $2,400 assuming all expenses apply and no prior claims. Run an alternate case where the employee loses the group coverage.</p></details>"},{"id":"course-3","title":"Course 3 · Investments and portfolio planning","html":"<h3>Course 3 · Investments and portfolio planning</h3><p>Complete the 9 topics below, then solve the applied case in the lesson menu. Explain the decision, assumptions and what would change your recommendation.</p><ol><li>Topic 27 · Investment vehicles and taxation</li><li>Topic 28 · Investment risks</li><li>Topic 29 · Market and economic cycles</li><li>Topic 30 · Returns and quantitative measures</li><li>Topic 31 · Allocation and diversification</li><li>Topic 32 · Valuing stocks and bonds</li><li>Topic 33 · Portfolio construction</li><li>Topic 34 · Investment strategy and implementation</li><li>Topic 35 · Alternatives and liquidity</li></ol>"},{"id":"topic-27","title":"Topic 27 · Investment vehicles and taxation","html":"<h3>Topic 27 · Investment vehicles and taxation</h3><p>Compare deposit instruments, bonds, equities, funds, ETFs and pooled structures by return source, risk, cost, liquidity and tax. Distinguish income, distributions and realized gains. A fund can distribute capital gains even where the shareholder has sold nothing.</p><h4>Knowledge check</h4><p>An investor in a taxable mutual fund reinvests a taxable distribution. How is it generally treated?</p><details><summary>Reveal answer</summary><p>Taxable when distributed, with reinvestment increasing basis.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-28","title":"Topic 28 · Investment risks","html":"<h3>Topic 28 · Investment risks</h3><p>Separate broad market risk from issuer-specific risk. Identify inflation, credit, interest-rate, currency, liquidity and concentration risks. Diversification reduces issuer-specific exposure but can leave broad market risk.</p><h4>Knowledge check</h4><p>Which risk is most directly reduced by holding many unrelated issuers?</p><details><summary>Reveal answer</summary><p>Company-specific risk</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-29","title":"Topic 29 · Market and economic cycles","html":"<h3>Topic 29 · Market and economic cycles</h3><p>Markets may anticipate economic turning points. Distinguish business cycles from asset-price trends and test plans under recession, inflation and rate shocks. Match liquidity to liabilities rather than timing every cycle.</p><h4>Knowledge check</h4><p>A client needs a down payment next year. What matters most for that allocation?</p><details><summary>Reveal answer</summary><p>Preserving near-term liquidity and principal.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-30","title":"Topic 30 · Returns and quantitative measures","html":"<h3>Topic 30 · Returns and quantitative measures</h3><p>Arithmetic return averages periods. Geometric return compounds them. Time-weighted return removes the influence of external cash flows. Money-weighted return reflects investor timing. Standard deviation measures dispersion and beta measures sensitivity to market moves.</p><h4>Knowledge check</h4><p>Returns are +25% then −20%, with no flows. What is the cumulative return?</p><details><summary>Reveal answer</summary><p>0%</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-31","title":"Topic 31 · Allocation and diversification","html":"<h3>Topic 31 · Allocation and diversification</h3><p>Set a strategic mix around horizon, tolerance and liquidity. Correlation determines how holdings move together. Use thresholds and tax-aware rebalancing to maintain risk exposure.</p><h4>Knowledge check</h4><p>Which addition offers more diversification when risk and return are otherwise comparable?</p><details><summary>Reveal answer</summary><p>A holding with low correlation to existing assets.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-32","title":"Topic 32 · Valuing stocks and bonds","html":"<h3>Topic 32 · Valuing stocks and bonds</h3><p>Discount expected cash flows. Bond prices generally move inversely with yields. Duration approximates price sensitivity for small yield changes. Dividend discount valuation depends heavily on growth and discount assumptions.</p><h4>Knowledge check</h4><p>Duration is 5 and yield rises 1 percentage point. Approximate price change before convexity?</p><details><summary>Reveal answer</summary><p>−5%</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-33","title":"Topic 33 · Portfolio construction","html":"<h3>Topic 33 · Portfolio construction</h3><p>Define the policy statement before implementation. Review expected return, volatility, beta, fees, benchmark and taxes. The Sharpe ratio compares excess return against total volatility.</p><h4>Knowledge check</h4><p>Portfolio return is 9%, risk-free rate 3%, and standard deviation 12%. What is the Sharpe ratio?</p><details><summary>Reveal answer</summary><p>0.50</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-34","title":"Topic 34 · Investment strategy and implementation","html":"<h3>Topic 34 · Investment strategy and implementation</h3><p>Compare active and passive, growth and value, buy-and-hold and rebalancing. Tax-loss harvesting changes taxes and basis and can be restricted by wash-sale rules. Options introduce nonlinear exposure. Measure fees and tracking against a relevant benchmark.</p><h4>Knowledge check</h4><p>What does a disciplined rebalancing rule primarily do?</p><details><summary>Reveal answer</summary><p>Returns the portfolio toward target risk exposures.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-35","title":"Topic 35 · Alternatives and liquidity","html":"<h3>Topic 35 · Alternatives and liquidity</h3><p>Private equity, hedge funds, direct real estate and commodities may have leverage, valuation uncertainty, lockups or redemption gates. Model capital calls and access to money during stress. A quoted valuation need not be a realizable selling price.</p><h4>Knowledge check</h4><p>What matters most when the client may need money during a redemption gate?</p><details><summary>Reveal answer</summary><p>Whether sufficient liquid assets remain available.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"case-3","title":"Applied case 3 · Investment analysis","html":"<h3>Applied case 3 · Investment analysis</h3><p>A $400,000 portfolio targets 60% stocks and 40% bonds. After market movement it holds $280,000 stocks and $120,000 bonds. The client has a separately funded two-year cash need.</p><h4>Your assignment</h4><p>Find the rebalance amount. Give a lower-tax implementation strategy and an investment policy rule.</p><details><summary>Reveal worked solution</summary><p>Target stocks are $240,000. Shift $40,000 from stocks to bonds, or use contributions and distributions to rebalance where appropriate. In taxable accounts check embedded gains, lots and loss offsets before selling.</p></details>"},{"id":"course-4","title":"Course 4 · Federal tax planning","html":"<h3>Course 4 · Federal tax planning</h3><p>Complete the 8 topics below, then solve the applied case in the lesson menu. Explain the decision, assumptions and what would change your recommendation.</p><ol><li>Topic 36 · Tax law and authority</li><li>Topic 37 · Income tax computation</li><li>Topic 38 · Business entities</li><li>Topic 39 · Trust and estate income tax</li><li>Topic 40 · Tax management</li><li>Topic 41 · Property transactions</li><li>Topic 42 · Special tax circumstances</li><li>Topic 43 · Charitable transfers</li></ol>"},{"id":"topic-36","title":"Topic 36 · Tax law and authority","html":"<h3>Topic 36 · Tax law and authority</h3><p>Use the Internal Revenue Code, regulations, applicable rulings, instructions and exam-year reference tables. Identify taxpayer, tax year, filing status and deadlines. Separate federal assumptions from state treatment.</p><h4>Knowledge check</h4><p>Which first step prevents mixing rules across tax years?</p><details><summary>Reveal answer</summary><p>Identify the applicable tax year and verify its current rules.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-37","title":"Topic 37 · Income tax computation","html":"<h3>Topic 37 · Income tax computation</h3><p>Start with gross income, subtract applicable adjustments to reach AGI, then deductions to compute taxable income. Apply rates and credits at the correct stage. Distinguish refundable and nonrefundable credits and effective versus marginal rates.</p><h4>Knowledge check</h4><p>At a 24% marginal rate, which usually reduces tax more if fully usable, a $1,000 deduction or $1,000 credit?</p><details><summary>Reveal answer</summary><p>The $1,000 credit.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-38","title":"Topic 38 · Business entities","html":"<h3>Topic 38 · Business entities</h3><p>A sole proprietor generally reports business income on the individual return. Partnerships and S corporations generally pass through tax items. C corporations are separate taxpayers. Compare payroll, basis, distributions, reasonable compensation, and applicable deduction restrictions.</p><h4>Knowledge check</h4><p>Which structure generally faces an entity-level federal corporate income tax as its standard treatment?</p><details><summary>Reveal answer</summary><p>C corporation</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-39","title":"Topic 39 · Trust and estate income tax","html":"<h3>Topic 39 · Trust and estate income tax</h3><p>Distinguish grantor from nongrantor treatment. A nongrantor trust or estate may deduct qualifying distributions and pass taxable items to beneficiaries through DNI limits and reporting. Retained income may face compressed brackets.</p><h4>Knowledge check</h4><p>What concept generally limits income carried out to beneficiaries by distributions?</p><details><summary>Reveal answer</summary><p>Distributable net income</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-40","title":"Topic 40 · Tax management","html":"<h3>Topic 40 · Tax management</h3><p>Compare timing of income and deductions, bracket management, asset location and gain realization. Test side effects on credits, Medicare premiums and future tax. Deferral changes timing and does not automatically eliminate tax.</p><h4>Knowledge check</h4><p>A low-income transition year precedes future required distributions. What should be modeled?</p><details><summary>Reveal answer</summary><p>Partial Roth conversion with current and future tax effects.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-41","title":"Topic 41 · Property transactions","html":"<h3>Topic 41 · Property transactions</h3><p>Gain generally equals net amount realized minus adjusted basis. Inherited and gifted property can have different basis rules. Distinguish capital gains, ordinary recapture and qualifying home-sale exclusions or like-kind real-property exchanges.</p><h4>Knowledge check</h4><p>Ignoring costs and exclusions, sale proceeds are $180,000 and adjusted basis is $120,000. What is gain?</p><details><summary>Reveal answer</summary><p>$60,000</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-42","title":"Topic 42 · Special tax circumstances","html":"<h3>Topic 42 · Special tax circumstances</h3><p>Evaluate alternative minimum tax, net investment income tax, passive-loss limits, divorce, stock compensation and cross-border issues separately. Check basis and holding dates before trading employer shares.</p><h4>Knowledge check</h4><p>An employee exercises incentive stock options and holds the shares. What additional exposure should be checked?</p><details><summary>Reveal answer</summary><p>Potential alternative minimum tax.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-43","title":"Topic 43 · Charitable transfers","html":"<h3>Topic 43 · Charitable transfers</h3><p>Compare cash and appreciated assets, eligibility, substantiation, deduction limits and carryforwards. Long-term appreciated shares donated to a qualifying charity can avoid realizing the gain and may qualify for a deduction under applicable rules. Evaluate QCDs and donor-advised funds independently.</p><h4>Knowledge check</h4><p>Which detail establishes the required evidence for a large noncash gift?</p><details><summary>Reveal answer</summary><p>Eligible recipient, valuation and applicable substantiation or appraisal.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"case-4","title":"Applied case 4 · Tax comparison","html":"<h3>Applied case 4 · Tax comparison</h3><p>An investor holds $50,000 of long-term appreciated shares with a $20,000 adjusted basis. Assume a 15% federal long-term gain rate, eligibility for qualified charity treatment and no other taxes for the comparison.</p><h4>Your assignment</h4><p>Compare selling and donating cash with donating shares directly. Explain what must be verified before estimating a deduction.</p><details><summary>Reveal worked solution</summary><p>Selling realizes $30,000 gain and $4,500 modeled tax, leaving $45,500 for the gift if tax comes from the proceeds. An eligible direct transfer can deliver $50,000 of value without the donor realizing that gain. Verify itemization, recipient, holding period, limits, valuation and documentation.</p></details>"},{"id":"course-5","title":"Course 5 · Retirement income and benefits","html":"<h3>Course 5 · Retirement income and benefits</h3><p>Complete the 10 topics below, then solve the applied case in the lesson menu. Explain the decision, assumptions and what would change your recommendation.</p><ol><li>Topic 44 · Retirement needs model</li><li>Topic 45 · Social Security and Medicare</li><li>Topic 46 · Eldercare and special needs</li><li>Topic 47 · Retirement plan types</li><li>Topic 48 · Qualified plan provisions</li><li>Topic 49 · Nonqualified plans</li><li>Topic 50 · Business plan selection</li><li>Topic 51 · Distribution and tax rules</li><li>Topic 52 · Retirement income strategy</li><li>Topic 53 · Business succession</li></ol>"},{"id":"topic-44","title":"Topic 44 · Retirement needs model","html":"<h3>Topic 44 · Retirement needs model</h3><p>Estimate retirement spending by category and subtract reliable income. Model inflation, tax, longevity and one-time costs. A capital target based on an initial withdrawal assumption is a screening estimate. Stress-test it.</p><h4>Knowledge check</h4><p>An annual $40,000 portfolio gap and a 4% initial draw imply what starting estimate?</p><details><summary>Reveal answer</summary><p>$1 million</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-45","title":"Topic 45 · Social Security and Medicare","html":"<h3>Topic 45 · Social Security and Medicare</h3><p>Compare early, full-retirement-age and delayed claiming, including survivor effects. Delay can raise the monthly benefit up to age 70. Medicare enrollment follows its own timing. Check employer coverage, enrollment windows, Part A retroactivity for HSA contributors, and income-related premiums.</p><h4>Knowledge check</h4><p>What should spouses model beyond individual break-even ages?</p><details><summary>Reveal answer</summary><p>The survivor’s benefit and household income after the first death.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-46","title":"Topic 46 · Eldercare and special needs","html":"<h3>Topic 46 · Eldercare and special needs</h3><p>Plan caregiving, housing, capacity, medical authority and resources. Discuss public benefits and specialized legal advice before leaving funds outright to someone whose benefits are means-tested.</p><h4>Knowledge check</h4><p>What action is appropriate before funding a beneficiary’s support through a direct inheritance?</p><details><summary>Reveal answer</summary><p>Coordinate with benefits and special-needs counsel.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-47","title":"Topic 47 · Retirement plan types","html":"<h3>Topic 47 · Retirement plan types</h3><p>Defined benefit plans promise a formula benefit and defined contribution plans provide an individual account. Compare 401(k), 403(b), governmental 457(b), SEP, SIMPLE, and individual retirement arrangements by sponsor, access and contributions.</p><h4>Knowledge check</h4><p>Which plan design promises a benefit determined by a formula?</p><details><summary>Reveal answer</summary><p>Defined benefit plan</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-48","title":"Topic 48 · Qualified plan provisions","html":"<h3>Topic 48 · Qualified plan provisions</h3><p>Review eligibility, vesting, nondiscrimination, contribution limits and distribution terms. Your own salary deferrals are generally vested immediately, while employer contributions can vest over time. Compare direct transfer with participant-paid distribution and withholding rules.</p><h4>Knowledge check</h4><p>Which process generally avoids mandatory federal withholding on an eligible employer-plan rollover distribution?</p><details><summary>Reveal answer</summary><p>Direct rollover to an eligible recipient plan or IRA</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-49","title":"Topic 49 · Nonqualified plans","html":"<h3>Topic 49 · Nonqualified plans</h3><p>Nonqualified deferred compensation can be selective and involve employer-credit risk and strict timing under Section 409A. Evaluate plan terms, funding, election flexibility and forfeiture.</p><h4>Knowledge check</h4><p>An unfunded nonqualified plan pays later. What additional risk should a participant assess?</p><details><summary>Reveal answer</summary><p>Employer insolvency risk.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-50","title":"Topic 50 · Business plan selection","html":"<h3>Topic 50 · Business plan selection</h3><p>Compare budget, owner goals, workforce demographics, administration, contribution flexibility and employee coverage. Model the cost of owners and staff together. Coordinate implementation with plan specialists.</p><h4>Knowledge check</h4><p>What should be compared before selecting a plan for a firm with high turnover?</p><details><summary>Reveal answer</summary><p>Eligibility, vesting, employer cost and administrative demands.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-51","title":"Topic 51 · Distribution and tax rules","html":"<h3>Topic 51 · Distribution and tax rules</h3><p>Check account type, age, beneficiary class, deadlines and exceptions before determining taxes. Distinguish conversions, rollovers, required minimum distributions, early distribution rules and qualified Roth distributions. Rules vary by birth cohort and account. Consult current IRS instructions.</p><h4>Knowledge check</h4><p>May an owner generally convert the current year’s required minimum distribution to Roth?</p><details><summary>Reveal answer</summary><p>No. The RMD itself is ineligible for rollover or conversion.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-52","title":"Topic 52 · Retirement income strategy","html":"<h3>Topic 52 · Retirement income strategy</h3><p>Use spending floors, flexible withdrawals, tax-aware sequencing and cash buffers. Sequence risk is particularly acute when losses coincide with withdrawals. Stress-test inflation, long life and early negative returns.</p><h4>Knowledge check</h4><p>Which retiree faces higher sequence risk, all else equal?</p><details><summary>Reveal answer</summary><p>One taking withdrawals during large early losses.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-53","title":"Topic 53 · Business succession","html":"<h3>Topic 53 · Business succession</h3><p>Plan management transition, ownership transfer, valuation, funding and contingency. Compare internal sale, third-party sale and family transfer. Reconcile owner retirement spending with net proceeds and installment or concentration risks.</p><h4>Knowledge check</h4><p>Which two needs must be modeled together before an owner retires on sale proceeds?</p><details><summary>Reveal answer</summary><p>Net sale proceeds and post-sale household cash flow.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"case-5","title":"Applied case 5 · Retirement stress test","html":"<h3>Applied case 5 · Retirement stress test</h3><p>Projected annual retirement spending is $92,000, including taxes. Reliable income is $52,000. Investable assets are $950,000. A 20% first-year decline strikes the entire portfolio before withdrawals.</p><h4>Your assignment</h4><p>Compute the initial draw rate and draw rate after the decline. Compare maintaining withdrawals, spending flexibility and a funded reserve.</p><details><summary>Reveal worked solution</summary><p>The portfolio gap is $40,000. Initial draw is 4.21%; after the shock, $40,000 ÷ $760,000 = 5.26% before the first withdrawal. Compare trade-offs, tax sequence and inflation effects. No single assumed withdrawal rate guarantees success.</p></details>"},{"id":"course-6","title":"Course 6 · Estate and succession planning","html":"<h3>Course 6 · Estate and succession planning</h3><p>Complete the 11 topics below, then solve the applied case in the lesson menu. Explain the decision, assumptions and what would change your recommendation.</p><ol><li>Topic 54 · Titling and beneficiary review</li><li>Topic 55 · Property transfer methods</li><li>Topic 56 · Estate and incapacity documents</li><li>Topic 57 · Gift, estate and GST calculation</li><li>Topic 58 · Estate liquidity</li><li>Topic 59 · Trusts and taxation</li><li>Topic 60 · Marital transfers</li><li>Topic 61 · Intra-family business transfers</li><li>Topic 62 · Post-death planning</li><li>Topic 63 · Divorce and unmarried partners</li><li>Topic 64 · Special-needs estate planning</li></ol>"},{"id":"topic-54","title":"Topic 54 · Titling and beneficiary review","html":"<h3>Topic 54 · Titling and beneficiary review</h3><p>Compare sole ownership, tenancy in common, survivorship forms and community property under applicable law. Named beneficiaries and contract terms can control transfer outside probate. Reconcile account records with intention after life events.</p><h4>Knowledge check</h4><p>Which typically controls payment on a validly designated life policy?</p><details><summary>Reveal answer</summary><p>The policy beneficiary designation.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-55","title":"Topic 55 · Property transfer methods","html":"<h3>Topic 55 · Property transfer methods</h3><p>Compare lifetime gifts, will transfers, funded trusts, survivorship and beneficiary designations. Consider control, privacy, creditor exposure, probate and tax basis. Verify actual titling and local rules.</p><h4>Knowledge check</h4><p>What allows a revocable trust to govern disposition of an individually titled asset during life?</p><details><summary>Reveal answer</summary><p>Valid funding or transfer of title to the trust where appropriate.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-56","title":"Topic 56 · Estate and incapacity documents","html":"<h3>Topic 56 · Estate and incapacity documents</h3><p>A will directs probate property and can nominate guardians. A financial power of attorney can authorize actions during incapacity. Health directives and healthcare authority address medical decisions. A funded trust can help manage assets. Coordinate execution with counsel.</p><h4>Knowledge check</h4><p>Which tool may authorize someone to pay bills during your incapacity?</p><details><summary>Reveal answer</summary><p>Durable financial power of attorney</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-57","title":"Topic 57 · Gift, estate and GST calculation","html":"<h3>Topic 57 · Gift, estate and GST calculation</h3><p>Identify donor, recipient, fair market value, transfer date and applicable annual or lifetime exclusions. Estate analysis starts with includible assets and applicable deductions. GST can apply to qualifying transfers to skip persons, separately from gift or estate rules. Determine filing and elections using current forms.</p><h4>Knowledge check</h4><p>When modeling a gift above an available annual exclusion, what must be checked before assuming cash tax is due?</p><details><summary>Reveal answer</summary><p>Prior gifts, available lifetime exclusion and reporting obligations.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-58","title":"Topic 58 · Estate liquidity","html":"<h3>Topic 58 · Estate liquidity</h3><p>List obligations, taxes, legal expenses, family support and restricted assets. Evaluate cash, insurance, credit and sale options plus timing. Verify who receives insurance proceeds and whether proceeds can legally fund estate obligations.</p><h4>Knowledge check</h4><p>The estate is mostly an illiquid family business. What should the planner quantify?</p><details><summary>Reveal answer</summary><p>Near-term cash needs and accessible funding without a forced sale.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-59","title":"Topic 59 · Trusts and taxation","html":"<h3>Topic 59 · Trusts and taxation</h3><p>Compare revocable, irrevocable, marital, bypass, special-needs and charitable trusts. Identify grantor, trustee, beneficiary and powers. Income tax treatment, estate inclusion and control are separate questions. Revocable grantor trust assets generally remain in the grantor’s taxable estate.</p><h4>Knowledge check</h4><p>Which party typically manages trust property under the instrument?</p><details><summary>Reveal answer</summary><p>Trustee</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-60","title":"Topic 60 · Marital transfers","html":"<h3>Topic 60 · Marital transfers</h3><p>Model qualifying marital deduction transfers, portability and bypass planning. Verify timely estate filings and elections. Consider citizen and noncitizen spouse rules, potential QDOT use and the limits of portability for GST and state taxes.</p><h4>Knowledge check</h4><p>How is federal portability generally elected?</p><details><summary>Reveal answer</summary><p>Through the applicable estate tax return and election process.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-61","title":"Topic 61 · Intra-family business transfers","html":"<h3>Topic 61 · Intra-family business transfers</h3><p>Compare gifts, sales, installment transactions and trust-based strategies. Model valuation, cash-flow, basis, control and family fairness. Obtain qualified appraisal and legal guidance where warranted.</p><h4>Knowledge check</h4><p>Why compare a sale and a gift of family-business interests?</p><details><summary>Reveal answer</summary><p>They can differ in tax, liquidity, control and succession effects.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-62","title":"Topic 62 · Post-death planning","html":"<h3>Topic 62 · Post-death planning</h3><p>Identify executor, asset values, deadlines, beneficiary options and relevant elections. Qualified disclaimers are time-sensitive and restrict acceptance and control. Consider portability, alternate valuation where eligible and distribution rules.</p><h4>Knowledge check</h4><p>What should a beneficiary do before accepting an asset they may disclaim?</p><details><summary>Reveal answer</summary><p>Consult counsel promptly about qualified disclaimer rules.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-63","title":"Topic 63 · Divorce and unmarried partners","html":"<h3>Topic 63 · Divorce and unmarried partners</h3><p>Review agreements, titles and state rights, insurance, beneficiary forms and retirement orders. A QDRO can divide qualifying employer-plan benefits under applicable plan rules. Unmarried partners may need explicit legal arrangements to meet their goals.</p><h4>Knowledge check</h4><p>What instrument can direct a qualified employer plan to assign benefits under a divorce settlement?</p><details><summary>Reveal answer</summary><p>A qualified domestic relations order</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"topic-64","title":"Topic 64 · Special-needs estate planning","html":"<h3>Topic 64 · Special-needs estate planning</h3><p>Coordinate beneficiary designations, special-needs trusts and ABLE accounts where eligible with benefits counsel. Evaluate fiduciary selection, caregiving succession and written instructions. The client’s benefit program and trust terms govern trade-offs.</p><h4>Knowledge check</h4><p>What is the first issue when a relative proposes giving cash directly to a person on means-tested benefits?</p><details><summary>Reveal answer</summary><p>Potential effect on eligibility and support before completing the gift.</p></details><h4>Practice transfer</h4><p>Write one fact you would verify with a client and how a change in that fact could change the analysis.</p>"},{"id":"case-6","title":"Applied case 6 · Estate and succession","html":"<h3>Applied case 6 · Estate and succession</h3><p>The surviving spouse needs immediate access to $125,000. The estate has $55,000 cash and $1.2 million in a closely held firm. A $300,000 policy names an adult child. An old retirement form names a former spouse.</p><h4>Your assignment</h4><p>Calculate estate cash gap, classify which transfers may bypass probate, and identify questions for counsel.</p><details><summary>Reveal worked solution</summary><p>The initial cash gap is $70,000. Do not count insurance named to the child as estate cash. Verify policy and retirement beneficiary forms, federal plan rules, relevant state law and agreements. Compare liquidity sources and fund the business transition.</p></details>"},{"id":"calculator","title":"Calculator lab and formula sheet","html":"<h3>Calculator lab and formula sheet</h3><table><thead><tr><th>Task</th><th>Setup</th><th>Check</th></tr></thead><tbody><tr><td>Future value</td><td>PV × (1+r)^n</td><td>$10,000 at 5% for 3 years yields $11,576.25.</td></tr><tr><td>Present value</td><td>FV ÷ (1+r)^n</td><td>$25,000 due in 5 years at 4% is about $20,548 today.</td></tr><tr><td>Ordinary annuity PV</td><td>PMT × [1 − (1+r)^−n] ÷ r</td><td>$10,000 at each year-end for 10 years at 4% is near $81,109.</td></tr><tr><td>Nominal to real</td><td>(1 + nominal rate) ÷ (1 + inflation) − 1</td><td>6% and 3% imply 2.91% real.</td></tr><tr><td>Net worth</td><td>Assets − liabilities</td><td>$420,000 − $265,000 = $155,000.</td></tr><tr><td>Portfolio performance</td><td>Multiply period growth factors and subtract 1</td><td>1.25 × 0.80 − 1 = 0%.</td></tr><tr><td>Bond price shock</td><td>−Modified duration × change in yield</td><td>5 × −0.01 ≈ −5%.</td></tr><tr><td>Portfolio gap</td><td>Spending − reliable income</td><td>$92,000 − $52,000 = $40,000.</td></tr></tbody></table><p>For calculator practice, clear TVM, set compounding and payment frequency, use opposite signs for cash received and paid, and use END unless payments occur at the start. Solve the same problems on a calculator and in a spreadsheet, then explain rounding differences.</p>"},{"id":"capstone","title":"Course 7 · Financial plan capstone","html":"<h3>Course 7 · Financial plan capstone</h3><h4>The Rivera household</h4><p>Alex, 47, earns $110,000 and Sam, 45, earns $65,000. They have children ages 10 and 14. Monthly take-home is $10,200 after payroll contributions. Essentials are $5,900, discretionary spending $1,500 and debt service $1,300. They hold $22,000 in cash, owe $19,000 at 19% on a credit card, and have a $275,000 mortgage at 3.9%. Their home is valued at $440,000. Retirement assets are $420,000 pretax, $55,000 Roth, and $62,000 taxable, with taxable basis $44,000. Each child has $15,000 in a 529. Alex has $100,000 employer life and a group disability policy whose terms are unknown. Sam has no reported life policy. Their wills predate the second child. Alex’s parents are beginning to need help.</p><p>Goals: fund six months of essential reserves, put $25,000 toward each child’s education in today’s dollars, retire when Alex is 65, and preserve $85,000 annual spending including taxes. Assume $48,000 annual reliable retirement income in today’s dollars for the initial model, a 3% real portfolio return, and 3.5–4% initial draw sensitivities. Treat these as exercise assumptions. The client has no stated risk tolerance or estate authority details.</p><h4>Required submissions</h4><ol><li>Prepare a two-page client executive summary, an engagement and conflict statement, and an assumptions and missing-data log.</li><li>Build a household balance sheet and cash-flow model. Compare at least two reserve/debt strategies and quantify the effect on spending and interest.</li><li>Estimate insurance needs and health/disability exposure. Recommend verification and compare individual and employer coverage.</li><li>Model education and retirement using real or nominal inputs consistently. Include a poor-return and early-retirement shock.</li><li>Show an investment policy, tax-aware funding order, beneficiary and incapacity checklist, and referrals to CPA or counsel.</li><li>Deliver an implementation worksheet and record a five-minute client presentation. Ask the client to explain the most important trade-off back to you.</li></ol><details><summary>Reveal model checkpoints</summary><p>Monthly surplus is $1,500. Six months of essentials is $35,400, leaving a $13,400 gap before considering minimum debt payments or irregular bills. Listed assets are $1,029,000 and listed liabilities $294,000 for $735,000 estimated net worth. Annual retirement gap is $37,000. Capital screening range is $925,000 at 4% to about $1.057 million at 3.5%. Existing $537,000 pretax, Roth and taxable investments grow to roughly $914,000 over 18 years at a hypothetical 3% real return before new savings, taxes and fees. Adjust taxable liquidity to account for realized gain and avoid treating every balance as equivalent after tax.</p><p>A defensible plan preserves a cash floor and attacks the 19% debt, protects any employer match, then allocates freed cash flow among reserves, education and retirement. Verify debt minimums, matches, benefit statements, coverage definitions, basis and ownership before implementation. Compare a lower-return forecast and show the effect of deferring retirement or reducing discretionary spending. Avoid counting the 529 balances for retirement.</p></details><h4>Instructor scorecard</h4><ol><li>Discovery, scope and ethics · 15 points</li><li>Quantitative accuracy and assumptions · 25 points</li><li>Alternatives and cross-domain integration · 25 points</li><li>Implementation and ongoing monitoring · 20 points</li><li>Client presentation and teach-back · 15 points</li></ol><p>Suggested internal pass: 80/100 and satisfactory correction of material errors involving client interests, assumptions or scope. A mentor grades the written plan and presentation.</p>"},{"id":"workbook","title":"Reusable advisor worksheets","html":"<h3>Reusable advisor worksheets</h3><h4>Copy these fields into your de-identified case workbook</h4><ol><li>Discovery: client priorities, decision-makers, engagement scope, conflicts, missing facts, time horizon and deadline.</li><li>Net worth: owner, asset or debt, balance, valuation date, liquidity, cost basis, beneficiary, source.</li><li>Cash flow: category, monthly amount, essential or discretionary, frequency, seasonality, owner and source.</li><li>Options matrix: current course, proposed alternative, estimated costs, taxes, risk, liquidity, assumptions, reason and follow-up.</li><li>Implementation: recommendation, responsible person, dependency, deadline, client decision, verification evidence.</li><li>Monitoring: metric, threshold, next review date, trigger and escalation owner.</li><li>Exam error log: topic, why I missed it, corrected rule, worked example and retest date.</li></ol><h4>Mentor session</h4><p>Use 10 minutes for recall, 20 for the worked example and 15 for a teach-back. Review calculations independently before comparing results. Keep real customer identifiers out of training submissions.</p>"}]','[{"prompt":"An advisor gets a higher commission on two otherwise similar products. What must happen before recommending the higher-paying one?","choices":["Disclose it and skip the comparison","Assess alternatives, disclose material conflict, obtain informed consent and manage the conflict. Recommend based on client interests.","Mention the commission after the sale","Choose it because it is approved by the firm"]},{"prompt":"An advisor receives a CFP Board notice about a regulator’s findings. Does the regulator’s closure automatically close the Board matter?","choices":["Only if the client agrees","No. Review the notice and follow the Board’s separate procedures.","Yes, always","Only if the advisor changes employers"]},{"prompt":"A stock falls 30% at a solvent broker. Which protection reimburses the loss?","choices":["SIPC covers every dollar","FDIC covers the first $250,000","Both cover half","Neither FDIC nor SIPC covers the market decline."]},{"prompt":"A planner with only a planning designation wants to sell an insurance policy. What comes first?","choices":["Obtain client permission and proceed","File an income-tax extension","Verify the relevant producer license and authority.","Use a personal disclosure only"]},{"prompt":"An application is denied based partly on a credit report. Which law principally governs notice concerning the report?","choices":["FCRA","SIPC","ERISA","FDIC deposit insurance"]},{"prompt":"A retiree needs $40,000 within one year. Two products have similar benefits, but one locks the funds for seven years. What factor can determine the recommendation?","choices":["Liquidity relative to the client’s actual spending need.","The highest gross payout alone","The largest sales incentive","The longest illustration"]},{"prompt":"A client requests a rollover recommendation but cannot supply the plan’s fee and distribution terms. What is the next step?","choices":["Promise the rollover is tax-free in all cases","Gather those facts before finalizing the comparison.","Recommend the rollover immediately","Select allocation first and disclose later"]},{"prompt":"Assets are $420,000 and liabilities $265,000. What is net worth?","choices":["$420,000","$155,000","$685,000","$265,000"]},{"prompt":"A self-employed family’s essentials are $5,200 monthly. Its six-month reserve target is?","choices":["$10,400","$26,000","$62,400","$31,200"]},{"prompt":"Holding payments and all other terms constant, which approach generally minimizes interest?","choices":["Largest balance first","Longest maturity first","Highest effective rate first","Smallest balance first in every case"]},{"prompt":"Nominal return is 6% and inflation 3%. What is the approximate exact real return?","choices":["2.91%, using 1.06 ÷ 1.03 − 1","9%","3.09%","6%"]},{"prompt":"What is $10,000 in three years at 5% annual compounding?","choices":["$11,576.25","$11,500.00","$10,500.00","$8,638.38"]},{"prompt":"Tuition is $20,000 today and rises 4% annually for 10 years. What is the first-year projected cost?","choices":["$13,511","About $29,605","$28,000","$20,800"]},{"prompt":"Which vehicle can typically keep the parent as account owner while designating a student beneficiary?","choices":["Federal Direct Loan","529 savings plan","Completed UTMA transfer owned by the minor","Student’s individual brokerage only"]},{"prompt":"Two aid offers differ in grants and unsubsidized loans. Which reduces the student’s cost without creating debt when conditions are met?","choices":["Unsubsidized loan","Private loan","Credit card advance","Grant"]},{"prompt":"Which payment can qualify for the direct tuition exclusion when all conditions are met?","choices":["Gift to a family brokerage account","A loan to pay books","Tuition paid directly to the school","Cash given to the student for housing"]},{"prompt":"A client can afford risk but panics at drawdowns. What should the planner assess?","choices":["Both financial risk capacity and emotional risk tolerance.","Capacity alone","The advisor’s risk profile","Only the most recent return"]},{"prompt":"A client refuses to sell solely because the stock is below its original purchase price. Which bias fits?","choices":["Anchoring","Recency","Diversification","Duration"]},{"prompt":"Partners disagree about emergency savings versus investing. Which opening is best?","choices":["Choose a product before discussing goals","Ask each partner what concern the money is intended to address.","Label one partner irrational","Ask the higher earner to decide"]},{"prompt":"A client overwhelmed by debt misses appointments. What is a useful first step?","choices":["Diagnose a mental disorder","Agree on one doable action and when to check in.","Send a complete investment plan without discussion","Threaten to end service immediately"]},{"prompt":"How can the planner check whether a client understands a surrender charge?","choices":["Ask only whether they signed","Read the entire contract aloud at speed","Show only the gross illustration","Ask the client to explain in their own words what happens if they exit early."]},{"prompt":"A recent widow requests a large irreversible transfer while confused. What should be prioritized?","choices":["Ignore the request indefinitely","Move everything into a single long-lockup product","Clarify authority, immediate needs and risks before acting.","Execute quickly without questions"]},{"prompt":"Which strategy best describes installing a sprinkler system?","choices":["Risk reduction","Risk avoidance","Insurance transfer","Speculation"]},{"prompt":"Which gap should typically be addressed before paying to insure small replaceable items?","choices":["A financially catastrophic exposure the client cannot absorb.","The most frequent $10 loss","Only risks with an existing claim","Any item with sentimental value"]},{"prompt":"After a $500 remaining deductible on a $2,500 allowed bill, what does the member pay at 20% coinsurance before the cap?","choices":["$1,000","$900","$500","$400"]},{"prompt":"A policy pays once a 90-day disability waiting period passes. What is that interval called?","choices":["Lookback period","Elimination period","Benefit period","Grace period"]},{"prompt":"Which feature directly addresses rising care costs over time?","choices":["A longer elimination period","A lower daily benefit","Noncontributory payroll","Inflation protection"]},{"prompt":"Why might tax deferral alone be insufficient to justify an annuity inside an IRA?","choices":["Annuities always distribute tax-free","The death benefit is always zero","The IRA already provides tax deferral.","An IRA always prohibits annuities"]},{"prompt":"A 20-year mortgage is the only coverage need. Which design most directly matches the stated duration?","choices":["Twenty-year term","Single-premium immediate annuity","Medicare supplement","One-year hospital indemnity"]},{"prompt":"A firm wants funds to buy a deceased partner’s interest. What must the insurance align with?","choices":["The buy-sell agreement.","The employee handbook only","The workers’ compensation form","The company’s general liability deductible"]},{"prompt":"If stated needs total $900,000 and available assets and existing coverage are $300,000, what is the starting gap?","choices":["$300,000","$600,000","$1.2 million","$900,000"]},{"prompt":"A new policy has a lower premium. What should be checked before surrendering the existing one?","choices":["The first year’s illustration alone","Replacement effects and the new policy’s issued terms.","Only the new monthly bill","Only the advisor’s commission"]},{"prompt":"An investor in a taxable mutual fund reinvests a taxable distribution. How is it generally treated?","choices":["Always deferred until sale","Always excluded as a gift","Taxed only as payroll","Taxable when distributed, with reinvestment increasing basis."]},{"prompt":"Which risk is most directly reduced by holding many unrelated issuers?","choices":["All inflation risk","All reinvestment risk","Company-specific risk","All market risk"]},{"prompt":"A client needs a down payment next year. What matters most for that allocation?","choices":["Preserving near-term liquidity and principal.","Predicting the best stock sector","Maximizing duration","Increasing leverage"]},{"prompt":"Returns are +25% then −20%, with no flows. What is the cumulative return?","choices":["0%","5%","2.5%","−5%"]},{"prompt":"Which addition offers more diversification when risk and return are otherwise comparable?","choices":["A second share class of the same asset","A holding with low correlation to existing assets.","More of the same issuer","A fund holding only existing positions"]},{"prompt":"Duration is 5 and yield rises 1 percentage point. Approximate price change before convexity?","choices":["0%","−5%","+5%","−1%"]},{"prompt":"Portfolio return is 9%, risk-free rate 3%, and standard deviation 12%. What is the Sharpe ratio?","choices":["0.75","1.50","2.00","0.50"]},{"prompt":"What does a disciplined rebalancing rule primarily do?","choices":["Eliminates every taxable sale","Predicts short-term direction","Returns the portfolio toward target risk exposures.","Guarantees the highest return"]},{"prompt":"What matters most when the client may need money during a redemption gate?","choices":["Whether sufficient liquid assets remain available.","Last quarter’s reported valuation alone","The manager’s projected exit price","Whether reporting is monthly"]},{"prompt":"Which first step prevents mixing rules across tax years?","choices":["Identify the applicable tax year and verify its current rules.","Use the previous year’s threshold automatically","Use the highest marginal rate for all income","Ignore state law in client work"]},{"prompt":"At a 24% marginal rate, which usually reduces tax more if fully usable, a $1,000 deduction or $1,000 credit?","choices":["Neither affects tax","The $1,000 credit.","They are always equal","The deduction reduces tax by $1,240"]},{"prompt":"Which structure generally faces an entity-level federal corporate income tax as its standard treatment?","choices":["Disregarded single-member LLC","C corporation","Sole proprietorship","General partnership"]},{"prompt":"What concept generally limits income carried out to beneficiaries by distributions?","choices":["Gross estate value","Annual gift exclusion","Medicare IRMAA","Distributable net income"]},{"prompt":"A low-income transition year precedes future required distributions. What should be modeled?","choices":["A nondeductible donation to avoid all tax","Selling every asset regardless of basis","Partial Roth conversion with current and future tax effects.","Conversion of every account automatically"]},{"prompt":"Ignoring costs and exclusions, sale proceeds are $180,000 and adjusted basis is $120,000. What is gain?","choices":["$60,000","$300,000","$180,000","$120,000"]},{"prompt":"An employee exercises incentive stock options and holds the shares. What additional exposure should be checked?","choices":["Potential alternative minimum tax.","Automatic estate tax","Gift tax on exercise in all cases","Medicare Part D enrollment"]},{"prompt":"Which detail establishes the required evidence for a large noncash gift?","choices":["The stock’s historical high","Eligible recipient, valuation and applicable substantiation or appraisal.","The donor’s informal estimate alone","The advisor’s verbal confirmation"]},{"prompt":"An annual $40,000 portfolio gap and a 4% initial draw imply what starting estimate?","choices":["$4 million","$1 million","$160,000","$400,000"]},{"prompt":"What should spouses model beyond individual break-even ages?","choices":["Only the younger spouse’s salary","The fund’s last-quarter return","Only life expectancy at birth","The survivor’s benefit and household income after the first death."]},{"prompt":"What action is appropriate before funding a beneficiary’s support through a direct inheritance?","choices":["Transfer everything into the beneficiary’s checking account","Remove every beneficiary without review","Coordinate with benefits and special-needs counsel.","Assume all programs disregard assets"]},{"prompt":"Which plan design promises a benefit determined by a formula?","choices":["Defined benefit plan","Traditional 401(k) alone","Roth IRA","Taxable brokerage"]},{"prompt":"Which process generally avoids mandatory federal withholding on an eligible employer-plan rollover distribution?","choices":["Direct rollover to an eligible recipient plan or IRA","Check payable to the participant followed by a deposit","Cash withdrawal to checking","Taking the distribution as wages"]},{"prompt":"An unfunded nonqualified plan pays later. What additional risk should a participant assess?","choices":["Immediate unrestricted distribution","Employer insolvency risk.","FDIC coverage on every promised dollar","Automatic qualified-plan portability"]},{"prompt":"What should be compared before selecting a plan for a firm with high turnover?","choices":["Only the name of the provider","Eligibility, vesting, employer cost and administrative demands.","Only the owner’s maximum contribution","Only investment performance"]},{"prompt":"May an owner generally convert the current year’s required minimum distribution to Roth?","choices":["Yes, when transferred directly","Yes, if under age 70","Yes, whenever tax is withheld","No. The RMD itself is ineligible for rollover or conversion."]},{"prompt":"Which retiree faces higher sequence risk, all else equal?","choices":["One with fully covered spending and no withdrawals in all cases","One who holds no market assets","One taking withdrawals during large early losses.","One with identical average return and losses late in retirement, always"]},{"prompt":"Which two needs must be modeled together before an owner retires on sale proceeds?","choices":["Net sale proceeds and post-sale household cash flow.","Current revenue and logo value only","Past purchase price and office rent only","The buyer’s preferred bank and brand name"]},{"prompt":"Which typically controls payment on a validly designated life policy?","choices":["The policy beneficiary designation.","A contrary informal letter","The planner’s notes","The oldest child’s verbal request"]},{"prompt":"What allows a revocable trust to govern disposition of an individually titled asset during life?","choices":["Naming an insurance agent as witness alone","Valid funding or transfer of title to the trust where appropriate.","Signing the trust alone in all cases","Adding the asset to a personal budget"]},{"prompt":"Which tool may authorize someone to pay bills during your incapacity?","choices":["A funeral invoice","Durable financial power of attorney","A will alone","A life insurance illustration"]},{"prompt":"When modeling a gift above an available annual exclusion, what must be checked before assuming cash tax is due?","choices":["Only the recipient’s federal income bracket","Only the bank transfer fee","The asset’s historical cost alone","Prior gifts, available lifetime exclusion and reporting obligations."]},{"prompt":"The estate is mostly an illiquid family business. What should the planner quantify?","choices":["Only the projected stock return","The successor’s annual leave balance","Near-term cash needs and accessible funding without a forced sale.","Only the appraised value"]},{"prompt":"Which party typically manages trust property under the instrument?","choices":["Trustee","Beneficiary automatically","Insurance producer","Tax preparer automatically"]},{"prompt":"How is federal portability generally elected?","choices":["Through the applicable estate tax return and election process.","Automatically by joint bank ownership","Through the surviving spouse’s W-2","By updating the will only"]},{"prompt":"Why compare a sale and a gift of family-business interests?","choices":["Neither needs documentation","They can differ in tax, liquidity, control and succession effects.","They have identical economics automatically","Both always eliminate tax"]},{"prompt":"What should a beneficiary do before accepting an asset they may disclaim?","choices":["Wait until all filing deadlines pass","Consult counsel promptly about qualified disclaimer rules.","Take and spend distributions first","Direct the asset to any chosen relative"]},{"prompt":"What instrument can direct a qualified employer plan to assign benefits under a divorce settlement?","choices":["A personal email to the advisor","A joint budget","A standard consumer credit report","A qualified domestic relations order"]},{"prompt":"What is the first issue when a relative proposes giving cash directly to a person on means-tested benefits?","choices":["Whether cash earns interest that day","Only the advisor’s compensation","Potential effect on eligibility and support before completing the gift.","Whether the donor can use a credit card"]}]','BBDCAABBDCAABBDCAABBDCAABBDCAABBDCAABBDCAABBDCAABBDCAABBDCAABBDCAABBDC');
